var i=[{title:`Миттєва енергія високої потужності`,text:`Система АТФ-креатинфосфат (фосфагенна) може швидко поповнювати АТФ під час коротких зусиль високої потужності, як-от стрибок, старт спринту чи важкий підхід. Вона може підтримувати максимальну віддачу лише недовго, що допомагає пояснити, чому кількох хвилин відпочинку може вистачити, щоб відновити результативність між важкими силовими чи швидкісними зусиллями.`},{title:`Швидкий розпад вуглеводів`,text:`Анаеробний гліколіз постачає АТФ із вуглеводів, і реакції, що його створюють, не потребують кисню. Він найважливіший під час важких зусиль тривалістю від кількох секунд до кількох хвилин. Лактат часто називають «відходами» або звинувачують як єдину причину болючості, але організм також використовує його як паливо й метаболічний сигнал.`},{title:`Тривала аеробна продукція`,text:`Окисний обмін у мітохондріях використовує кисень, щоб створювати АТФ із вуглеводів і жирів. Він забезпечує довгі прогулянки, їзду на велосипеді, рівний біг і значну частину відновлення між важкими інтервалами. Навіть короткі зусилля отримують певний аеробний внесок, бо системи ніколи не вмикаються й вимикаються в окремих часових відсіках.`},{title:`Чому важливі тривалість і відпочинок`,text:`Майже максимальний п’ятисекундний спринт і 30-хвилинна прогулянка потребують дуже різної потужності. Повторювані 20-секундні важкі інтервали з коротким відпочинком ускладнюють підтримку віддачі, коли наростає втома. Важкі підходи зі штангою зазвичай потребують довшого відпочинку, щоб зберегти силу й техніку, а мета не в тому, щоб задихатися якомога сильніше.`},{title:`Застосування на практиці`,text:`Давайте собі достатньо відновлення, коли головна ціль: сила чи швидкість. Використовуйте рівну помірну активність, щоб розвивати аеробні можливості. Використовуйте інтервали для кондиції, коли вони підходять, і задавайте роботу та відпочинок під ваші нинішні можливості. Високий пульс під час підйому ваг не означає, що заняття дало такий самий аеробний стимул, як тривале кардіо.`}];var l=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Рекомендації ВООЗ щодо аеробної активності`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};